    public function test_list(): void
    {
        $this->fakeResponse(['data' => [['id' => '8e784c3e-afe8-4844-bb93-6b445763', 'payment' => 'pay_080225913252', 'installment' => 'b8dd74c-d078-40a0-9ae1-61a66c61a204', 'customerAccount' => 'cus_000000004085']], 'object' => 'list', 'hasMore' => false, 'totalCount' => 2, 'limit' => 10, 'offset' => 0]);

