        $this->assertRequestSent('GET', '/v3/chargebacks/', ['offset' => 0, 'limit' => 10, 'originDisputeDate[le]' => '2026-01-31']);
        $this->assertInstanceOf(ChargebackList::class, $result);
    }

    public function test_get(): void
    {
        $this->fakeResponse(['id' => '8e784c3e-afe8-4844-bb93-6b445763', 'payment' => 'pay_080225913252', 'installment' => 'b8dd74c-d078-40a0-9ae1-61a66c61a204', 'customerAccount' => 'cus_000000004085', 'status' => 'REQUESTED', 'reason' => 'ABSENCE_OF_PRINT', 'disputeStartDate' => '2026-01-31', 'value' => 2323.45, 'paymentDate' => '2026-01-31', 'creditCard' => ['number' => '8829', 'brand' => 'VISA']]);

        $result = asaas()->chargeback->get('id_1');

        $this->assertRequestSent('GET', '/v3/payments/id_1/chargeback');
        $this->assertInstanceOf(Chargeback::class, $result);
