        $this->fakeResponse(['chargebackId' => '2765d086-c7c5-5cca-898a-4262d212587c', 'status' => 'REQUESTED', 'files' => ['test_files']]);

        $result = asaas()->chargeback->createDispute('id_1', ['files' => UploadedFile::fake()->create('document.pdf', 10)]);

